  type: 'spec' | 'issue' | 'feedback' | 'external'
  title: string
  content?: string
  priority?: number
  tags?: string[]
  parent_id?: string

  // Issue-specific
  status?: string
  assignee?: string

  // Feedback-specific
  target_id?: string
