interface QueryEngine {
  // === Basic Queries ===
  nodes(filter: NodeFilter): Promise<Node[]>
  edges(filter: EdgeFilter): Promise<Edge[]>

  // === Relationship Queries ===
  edgesFrom(nodeId: string, type?: EdgeType): Promise<Edge[]>
