### `src/graph/sync.ts`

Sync logic between JSONL and SQLite.

```typescript
interface SyncManager {
  /** Mark node as dirty (needs JSONL sync) */
  markDirty(nodeId: string): void

  /** Schedule flush (debounced) */
  scheduleFlush(): void

  /** Force immediate flush */
  flush(): Promise<void>

  /** Cancel pending flush */
  cancel(): void
}

function createSyncManager(
  config: { debounceMs: number; maxDelayMs: number },
  jsonl: JSONLPersister,
  sqlite: SQLitePersister
): SyncManager
```

## Write Path

```
createNode(input):
  1. validation.validateCreateNode(input) → throw if invalid
  2. Generate ID and UUID
  3. Build StoredNode with timestamps
  4. sqlite.createNode(storedNode)
  5. syncManager.markDirty(id)
  6. syncManager.scheduleFlush()
  7. Return parsed Node
```

## Flush Logic

```typescript
async function flush(): Promise<void> {
  // 1. Get dirty node IDs
  const dirtyIds = await sqlite.getDirtyNodes()
  if (dirtyIds.length === 0) return

  // 2. Load current JSONL
  const { nodes, edges } = await jsonl.load()

  // 3. Build maps for efficient lookup
  const nodeMap = new Map(nodes.map(n => [n.id, n]))
  const edgeMap = new Map(edges.map(e => [e.id, e]))

  // 4. For each dirty node, get current state from SQLite
  for (const id of dirtyIds) {
    const current = await sqlite.getNode(id)
    if (current) {
      nodeMap.set(id, current)
    } else {
      nodeMap.delete(id)  // Was deleted
    }
  }

  // 5. Atomic write to JSONL
  await jsonl.save(
    Array.from(nodeMap.values()),
    Array.from(edgeMap.values())
  )

  // 6. Clear dirty flags
  await sqlite.clearDirty(dirtyIds)
}
```

## Debounced Flush

```typescript
class SyncManager {
  private debounceTimer: NodeJS.Timeout | null = null
  private maxDelayTimer: NodeJS.Timeout | null = null
  private flushPromise: Promise<void> | null = null

  scheduleFlush(): void {
    // Clear existing debounce
    if (this.debounceTimer) {
      clearTimeout(this.debounceTimer)
    }

    // Set debounce timer
    this.debounceTimer = setTimeout(() => {
      this.flush()
    }, this.config.debounceMs)

    // Set max delay timer (only once)
    if (!this.maxDelayTimer) {
      this.maxDelayTimer = setTimeout(() => {
        this.flush()
      }, this.config.maxDelayMs)
    }
  }

  async flush(): Promise<void> {
    // Clear timers
    if (this.debounceTimer) clearTimeout(this.debounceTimer)
    if (this.maxDelayTimer) clearTimeout(this.maxDelayTimer)
    this.debounceTimer = null
    this.maxDelayTimer = null

    // Actual flush
    await this.doFlush()
  }
}
```

