**Implementation Details:**

```typescript
class OpenTasksClient {
  private client: IPCClient
  private options: Required<ClientOptions>

  constructor(options?: ClientOptions) {
    this.options = {
      socketPath: options?.socketPath ?? getDefaultSocketPath(),
      autoConnect: options?.autoConnect ?? true,
      timeout: options?.timeout ?? 30000,
    }
    this.client = createIPCClient(this.options.socketPath)
  }

  async connect(): Promise<void> {
    await this.client.connect()
  }

  disconnect(): void {
    this.client.disconnect()
  }

  get connected(): boolean {
    return this.client.connected
  }

  private async ensureConnected(): Promise<void> {
    if (!this.connected && this.options.autoConnect) {
      await this.connect()
    }
    if (!this.connected) {
      throw new Error('Not connected to daemon')
    }
  }

  async link(params: LinkParams): Promise<LinkResult> {
    await this.ensureConnected()
    return this.client.request('tools.link', params)
  }

  async query(params: QueryParams): Promise<QueryResult> {
    await this.ensureConnected()
    return this.client.request('tools.query', params)
  }

  async annotate(params: AnnotateParams): Promise<AnnotateResult> {
    await this.ensureConnected()
    return this.client.request('tools.annotate', params)
  }

  // Convenience methods
  async ready(options?: ReadyOptions): Promise<NodeSummary[]> {
    const result = await this.query({ ready: options || {} })
    return result.items as NodeSummary[]
  }

  async blockers(nodeId: string, options?: BlockerOptions): Promise<NodeSummary[]> {
    const result = await this.query({ 
      blockers: { node_id: nodeId, ...options } 
    })
    return result.items as NodeSummary[]
  }

  async blocking(nodeId: string, options?: BlockerOptions): Promise<NodeSummary[]> {
    const result = await this.query({ 
      blocking: { node_id: nodeId, ...options } 
    })
    return result.items as NodeSummary[]
  }

  async feedback(nodeId: string, options?: FeedbackOptions): Promise<FeedbackSummary[]> {
    const result = await this.query({ 
      feedback: { node_id: nodeId, ...options } 
    })
    return result.items as FeedbackSummary[]
  }
}
