server.handle<LinkParams, LinkResult>('tools.link', async (params) => {
  const result = await link(store, params)
  if (result.success) {
    flushManager.markDirty(params.from_id)
    flushManager.markDirty(params.to_id)
    flushManager.schedule()
  }
  return result
