**Implementation Details:**

```typescript
class ProviderRegistryImpl implements ProviderRegistry {
  private providers = new Map&lt;string, Provider&gt;()
  private schemeMap = new Map&lt;string, Provider&gt;()

  register(provider: Provider): void {
    this.providers.set(provider.name, provider)
    for (const scheme of provider.schemes) {
      this.schemeMap.set(scheme, provider)
    }
  }

  resolveProvider(idOrUri: string): Provider | null {
    // Check if it's a URI with scheme
    const schemeMatch = idOrUri.match(/^([a-z]+):\/\//)
    if (schemeMatch) {
      return this.schemeMap.get(schemeMatch[1]) || null
    }

    // Check if it's a local ID (s-, i-, f-, e-, x-)
    if (/^[sifex]-[a-z0-9]+$/.test(idOrUri)) {
      return this.providers.get('native') || null
    }

    // Try each provider's parseUri
    for (const provider of this.providers.values()) {
      if (provider.parseUri(idOrUri)) {
        return provider
      }
    }

    return null
  }
}
```

