```typescript
startBackgroundSync(store: GraphStore, registry: ProviderRegistry): void {
  this.syncInterval = setInterval(async () =&gt; {
    // Find all stale external nodes
    const staleNodes = await store.query.nodes({
      type: 'external',
      materialized: true,
    }).filter(n =&gt; this.isStale(n))

    // Refresh each
    for (const node of staleNodes) {
      const provider = registry.resolveProvider(node.uri)
      if (provider) {
        await this.refresh(node, provider)
      }
    }
  }, this.config.backgroundSyncInterval)
}
