```typescript
// In createGraphStore:
const registry = config.providers ?? createProviderRegistry()
const materialization = createMaterializationManager(config.materialization)

// Auto-register native provider
const nativeProvider = createNativeProvider(store)
registry.register(nativeProvider)

// resolveNode implementation
async function resolveNode(idOrUri: string, options?: ResolveOptions) {
  // 1. Check if local ID
  if (isLocalId(idOrUri)) {
    return getNode(idOrUri)
  }

  // 2. Check for cached materialized node
  if (!options?.refresh) {
    const existing = await findExternalNodeByUri(idOrUri)
    if (existing && !materialization.isStale(existing)) {
      return existing
    }
  }

  // 3. Find provider and fetch
  const provider = registry.resolveProvider(idOrUri)
  if (!provider) {
    return null
  }

  const parsed = provider.parseUri(idOrUri)
  if (!parsed) return null

  const providerNode = await provider.get(parsed.id)
  if (!providerNode) return null

  // 4. Materialize if requested or per strategy
  const shouldMaterialize = materialization.shouldMaterialize(idOrUri, {
    accessType: 'resolve',
    explicit: options?.materialize,
  })

  if (shouldMaterialize) {
    return materialization.materialize(idOrUri, providerNode, store)
  }

  return providerNode
}
